create table if not exists public.recruitment_ui_settings(id integer primary key default 1 check(id=1),candidate_title text not null,candidate_title_en text not null,candidate_intro text not null,candidate_intro_en text not null,admin_title text not null,admin_title_en text not null,admin_intro text not null,admin_intro_en text not null,help_title text not null,help_title_en text not null,help_text text not null,help_text_en text not null,updated_at timestamptz not null default now());
alter table public.recruitment_ui_settings enable row level security;drop policy if exists "Public reads recruitment UI" on public.recruitment_ui_settings;drop policy if exists "Admins manage recruitment UI" on public.recruitment_ui_settings;create policy "Public reads recruitment UI" on public.recruitment_ui_settings for select using(true);create policy "Admins manage recruitment UI" on public.recruitment_ui_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into public.recruitment_ui_settings values(1,'Suivez votre candidature','Track your application','Suivez l’avancement de votre candidature au sein de NutVitaGlobalis.','Follow the progress of your application at NutVitaGlobalis.','Recrutement du personnel','Staff recruitment','Pilotez le recrutement des nutritionnistes et du personnel, de la candidature à l’intégration.','Manage nutritionist and staff recruitment from application to onboarding.','Besoin d’aide ?','Need help?','Notre équipe RH est disponible pour toute question concernant votre candidature.','Our HR team is available for any question about your application.',now()) on conflict(id) do nothing;
